<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,computed,watch} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,message} from '../api/client'
import {formatDate} from '../ui/branding'
import ManagementTabs from '../components/ManagementTabs.vue'
import {securityTabs,securityValues,acceptSecuritySave,clone,same} from '../ui/securityDraft'
const route=useRoute(),router=useRouter()
const tab=computed(()=>typeof route.query.tab==='string'&&Object.prototype.hasOwnProperty.call(securityTabs,route.query.tab)?route.query.tab:'global_access')
const config=ref<any>(null),baseline=ref<any>(null),currentIP=ref(''),loading=ref(false),saving=ref(false),loadError=ref('')
const dirtyTabs=computed(()=>config.value&&baseline.value?Object.keys(securityTabs).filter(key=>!same(securityValues(config.value,key),securityValues(baseline.value,key))):[])
const currentDirty=computed(()=>dirtyTabs.value.includes(tab.value)),pending=computed(()=>dirtyTabs.value.length>0)
const otherDrafts=computed(()=>dirtyTabs.value.filter(key=>key!==tab.value).map(key=>securityTabs[key]))
const isAccess=computed(()=>['global_access','admin_access','api_access'].includes(tab.value))
const scopeNotes:Record<string,string>={global_access:'适用于管理后台和 AI API。封禁规则优先于访问规则。',admin_access:'保护 /admin/* 页面、后台接口和登录接口。默认关闭，所有来源均可访问登录页。',api_access:'保护 /v1/* 接口。API Key IP 绑定独立生效，关闭来源限制不会解除绑定。'}
const search=ref(''),banStatus=ref(''),bindingSearch=ref('')
const networkRows=computed(()=>{const list=tab.value==='proxies'?config.value?.trusted_proxies:config.value?.[tab.value]?.addresses;return (list||[]).map((address:string,index:number)=>({address,index,type:address.includes('/')&&!address.endsWith(address.includes(':')?'/128':'/32')?'CIDR 网段':'单个 IP',family:address.includes(':')?'IPv6':'IPv4'})).filter((row:any)=>row.address.toLowerCase().includes(search.value.trim().toLowerCase()))})
const networkCount=computed(()=>tab.value==='proxies'?config.value?.trusted_proxies.length||0:config.value?.[tab.value]?.addresses.length||0)
const networkPage=ref(1),networkSize=ref(20),bindingPage=ref(1),bindingSize=ref(20),banPage=ref(1),banSize=ref(20)
const networkPageRows=computed(()=>networkRows.value.slice((networkPage.value-1)*networkSize.value,networkPage.value*networkSize.value))
const networkDialog=ref(false),networkTab=ref(''),networkIndex=ref<number|null>(null),networkInput=ref(''),validating=ref(false)
const keys=ref<any[]>([]),keysReady=ref(false),keysLoading=ref(false),keysError=ref('')
const bindingDialog=ref(false),bindingIndex=ref<number|null>(null),bindingForm=ref<{key_id:number|null;addresses:string}>({key_id:null,addresses:''})
const keyLabel=(id:number)=>keys.value.find(key=>key.id===id)?.label||'API Key #'+id
const bindingRows=computed(()=>(config.value?.key_bindings||[]).map((binding:any,index:number)=>({...binding,index,label:keyLabel(binding.key_id)})).filter((binding:any)=>(binding.label+' '+binding.addresses.join(' ')).toLowerCase().includes(bindingSearch.value.trim().toLowerCase())))
const bindingPageRows=computed(()=>bindingRows.value.slice((bindingPage.value-1)*bindingSize.value,bindingPage.value*bindingSize.value))
const banDialog=ref(false),banIndex=ref<number|null>(null),banForm=ref({address:'',reason:'',permanent:false,minutes:60})
const clockNow=ref(Date.now());let clockTimer:ReturnType<typeof setInterval>|undefined
const expired=(value:string|null)=>!!value&&new Date(value).getTime()<=clockNow.value
const banRows=computed(()=>(config.value?.bans||[]).map((ban:any,index:number)=>({...ban,index,state:expired(ban.expires_at)?'expired':ban.expires_at?'temporary':'permanent'})).filter((ban:any)=>(ban.address+' '+ban.reason).toLowerCase().includes(search.value.trim().toLowerCase())&&(!banStatus.value||ban.state===banStatus.value)))
const banPageRows=computed(()=>banRows.value.slice((banPage.value-1)*banSize.value,banPage.value*banSize.value))
watch([search,tab],()=>{networkPage.value=1;banPage.value=1})
watch(bindingSearch,()=>bindingPage.value=1)
watch(banStatus,()=>banPage.value=1)
watch(()=>networkRows.value.length,total=>networkPage.value=Math.min(networkPage.value,Math.max(1,Math.ceil(total/networkSize.value))))
watch(()=>bindingRows.value.length,total=>bindingPage.value=Math.min(bindingPage.value,Math.max(1,Math.ceil(total/bindingSize.value))))
watch(()=>banRows.value.length,total=>banPage.value=Math.min(banPage.value,Math.max(1,Math.ceil(total/banSize.value))))
const events:Record<string,string>={IP_BANNED:'IP 封禁拒绝',BLACKLIST_HIT:'黑名单命中',WHITELIST_REJECTED:'白名单拒绝',RATE_LIMITED:'请求限流',LOGIN_FAILED:'登录失败',ACCOUNT_LOCKED:'账号锁定',API_KEY_IP_MISMATCH:'API Key IP 不匹配',gateway_security_updated:'安全配置更新',gateway_security_recovered:'服务器恢复访问'}
const logItems=ref<any[]>([]),total=ref(0),page=ref(1),pageSize=ref(20),logIP=ref(''),logEvent=ref(''),logRange=ref<any[]>([]),logLoading=ref(false),logsReady=ref(false),logError=ref(''),logDetail=ref<any>(null),detailLoading=ref(false),detailOpen=ref(false)
const selectedLogIP=ref(''),selectedLogEvent=ref(''),selectedLogRange=ref<any[]>([])
const split=(value:string)=>[...new Set(value.split(/[\n,;，；]+/).map(item=>item.trim()).filter(Boolean))]
const requests=new Set<AbortController>();let disposed=false,logGeneration=0,detailGeneration=0
function options(){const request=new AbortController();requests.add(request);return {request,signal:request.signal,timeout:15000}}
async function confirmDiscard(text='有尚未保存的更改，离开将放弃这些更改。'){try{await ElMessageBox.confirm(text,'未保存更改',{confirmButtonText:'放弃更改',cancelButtonText:'继续编辑',type:'warning'});return true}catch{return false}}
async function changeTab(next:string){if(saving.value)return;await router.replace({query:{...route.query,tab:next}})}
async function load(){if(loading.value)return;loading.value=true;loadError.value='';const request=options();try{const result=await api.get('/admin/gateway-security',request);if(disposed)return;config.value=result.data.data.policy;baseline.value=clone(config.value);currentIP.value=result.data.data.current_ip}catch(error){if(!request.signal.aborted)loadError.value=message(error)}finally{requests.delete(request.request);if(!disposed)loading.value=false}}
async function reload(){if(saving.value)return;if(pending.value&&!await confirmDiscard('重新加载将放弃所有标签中尚未保存的修改。'))return;await load();if(tab.value==='api_access')void loadKeys(true);if(tab.value==='logs')void loadLogs()}
function resetCurrent(){for(const [field,value] of Object.entries(securityValues(baseline.value,tab.value)))config.value[field]=clone(value)}
async function save(){if(!currentDirty.value||saving.value)return;const section=tab.value,values=securityValues(config.value,section);saving.value=true;try{const result=await api.patch('/admin/gateway-security',{revision:baseline.value.revision,section,values},{timeout:15000});if(disposed)return;acceptSecuritySave(config.value,baseline.value,values,result.data.data.policy);currentIP.value=result.data.data.current_ip;ElMessage.success(securityTabs[section]+'已保存并生效');logsReady.value=false}catch(error){if(!disposed)ElMessage.error(message(error))}finally{if(!disposed)saving.value=false}}
async function normalize(input:string,purpose='addresses'){const addresses=split(input);if(!addresses.length)throw new Error('请填写 IP 或 CIDR 网段');if(addresses.length>500)throw new Error('一次最多添加 500 条地址');const result=await api.post('/admin/gateway-security/validate-addresses',{addresses,purpose},{timeout:15000});return result.data.data.addresses as string[]}
const validationMessage=(error:any)=>error.response?message(error):error.message||'请检查输入内容'
function editNetwork(index:number|null=null){networkTab.value=tab.value;networkIndex.value=index;networkInput.value=index===null?'':(tab.value==='proxies'?config.value.trusted_proxies:config.value[tab.value].addresses)[index];networkDialog.value=true}
async function addCurrentIP(){validating.value=true;try{const values=await normalize(currentIP.value);const list=config.value[tab.value].addresses;if(!list.includes(values[0])){if(list.length>=500)throw new Error('地址列表最多保留 500 条');list.push(values[0]);ElMessage.success('已加入当前管理员 IP，保存后生效')}else ElMessage.info('当前管理员 IP 已在列表中')}catch(error){ElMessage.error(validationMessage(error))}finally{validating.value=false}}
async function saveNetwork(){validating.value=true;try{const values=await normalize(networkInput.value,networkTab.value==='proxies'?'proxies':'addresses');if(networkIndex.value!==null&&values.length!==1)throw new Error('编辑时请只填写一个 IP 或网段');const list=networkTab.value==='proxies'?config.value.trusted_proxies:config.value[networkTab.value].addresses;const next=networkIndex.value===null?[...list,...values]:list.map((value:string,index:number)=>index===networkIndex.value?values[0]:value);const unique=[...new Set(next)];if(unique.length>(networkTab.value==='proxies'?100:500))throw new Error(networkTab.value==='proxies'?'可信代理最多保留 100 条':'地址列表最多保留 500 条');if(networkTab.value==='proxies')config.value.trusted_proxies=unique;else config.value[networkTab.value].addresses=unique;networkDialog.value=false;ElMessage.success('地址列表已更新，保存后生效')}catch(error){ElMessage.error(validationMessage(error))}finally{validating.value=false}}
function removeNetwork(index:number){(tab.value==='proxies'?config.value.trusted_proxies:config.value[tab.value].addresses).splice(index,1)}
async function loadKeys(force=false){if(keysLoading.value||keysReady.value&&!force)return;keysLoading.value=true;keysError.value='';const request=options();try{const result=await api.get('/admin/gateway-security/keys',request);if(!disposed){keys.value=result.data.data;keysReady.value=true}}catch(error){if(!request.signal.aborted)keysError.value=message(error)}finally{requests.delete(request.request);if(!disposed)keysLoading.value=false}}
function editBinding(index:number|null=null){bindingIndex.value=index;const current=index===null?null:config.value.key_bindings[index];bindingForm.value={key_id:current?.key_id||null,addresses:current?.addresses.join('\n')||''};bindingDialog.value=true;void loadKeys()}
async function saveBinding(){if(!bindingForm.value.key_id){ElMessage.warning('请选择 API Key');return}validating.value=true;try{const addresses=await normalize(bindingForm.value.addresses);if(addresses.length>100)throw new Error('每个 API Key 最多绑定 100 条地址');const id=bindingForm.value.key_id;if(config.value.key_bindings.some((binding:any,index:number)=>binding.key_id===id&&index!==bindingIndex.value))throw new Error('此 API Key 已有绑定，请编辑现有规则');const value={key_id:id,addresses};if(bindingIndex.value===null){if(config.value.key_bindings.length>=1000)throw new Error('最多保留 1000 个 API Key 绑定');config.value.key_bindings.push(value)}else config.value.key_bindings[bindingIndex.value]=value;bindingDialog.value=false;ElMessage.success('绑定已更新，保存后生效')}catch(error){ElMessage.error(validationMessage(error))}finally{validating.value=false}}
function editBan(index:number|null=null){banIndex.value=index;const current=index===null?null:config.value.bans[index];banForm.value={address:current?.address||'',reason:current?.reason||'',permanent:!!current&&!current.expires_at,minutes:current?.expires_at?Math.max(1,Math.ceil((new Date(current.expires_at).getTime()-Date.now())/60000)):60};banDialog.value=true}
async function saveBan(){validating.value=true;try{const addresses=await normalize(banForm.value.address);if(addresses.length!==1)throw new Error('每条封禁请填写一个 IP 或网段');if(!banForm.value.permanent&&(!Number.isInteger(banForm.value.minutes)||banForm.value.minutes<1||banForm.value.minutes>525600))throw new Error('临时封禁时长应为 1 至 525600 分钟');const address=addresses[0];if(config.value.bans.some((ban:any,index:number)=>ban.address===address&&index!==banIndex.value))throw new Error('此地址已有封禁记录，请编辑现有记录');const value={address,expires_at:banForm.value.permanent?null:new Date(Date.now()+banForm.value.minutes*60000).toISOString(),reason:banForm.value.reason.trim()};if(banIndex.value===null){if(config.value.bans.length>=500)throw new Error('最多保留 500 条封禁');config.value.bans.push(value)}else config.value.bans[banIndex.value]=value;banDialog.value=false;ElMessage.success('封禁配置已更新，保存后生效')}catch(error){ElMessage.error(validationMessage(error))}finally{validating.value=false}}
async function removeBan(index:number){try{await ElMessageBox.confirm('解除后该来源仍须通过其他 IP 规则。保存当前标签后生效。','解除封禁',{type:'warning',confirmButtonText:'解除封禁',cancelButtonText:'取消'})}catch{return}config.value.bans.splice(index,1)}
function queryLogs(){if(logRange.value?.length===2){const delta=new Date(logRange.value[1]).getTime()-new Date(logRange.value[0]).getTime();if(delta<=0||delta>31*86400000){ElMessage.warning('时间范围须大于 0 且不超过 31 天');return}}selectedLogIP.value=logIP.value.trim();selectedLogEvent.value=logEvent.value;selectedLogRange.value=clone(logRange.value||[]);page.value=1;void loadLogs()}
function resetLogs(){logIP.value='';logEvent.value='';logRange.value=[];queryLogs()}
async function loadLogs(){const version=++logGeneration,request=options();logLoading.value=true;logError.value='';try{const result=await api.get('/admin/gateway-security/logs',{...request,params:{page:page.value,size:pageSize.value,ip:selectedLogIP.value||undefined,event:selectedLogEvent.value||undefined,start:selectedLogRange.value[0]?new Date(selectedLogRange.value[0]).toISOString():undefined,end:selectedLogRange.value[1]?new Date(selectedLogRange.value[1]).toISOString():undefined}});if(disposed||version!==logGeneration)return;logItems.value=result.data.data.items;total.value=result.data.data.total;logsReady.value=true}catch(error){if(!request.signal.aborted&&version===logGeneration){logError.value=message(error);logItems.value=[];total.value=0}}finally{requests.delete(request.request);if(!disposed&&version===logGeneration)logLoading.value=false}}
async function showLog(row:any){const version=++detailGeneration;detailOpen.value=true;logDetail.value=null;detailLoading.value=true;try{const result=await api.get('/admin/gateway-security/logs/'+row.id,{timeout:15000});if(version===detailGeneration&&!disposed)logDetail.value=result.data.data}catch(error){if(version===detailGeneration&&!disposed){ElMessage.error(message(error));detailOpen.value=false}}finally{if(version===detailGeneration&&!disposed)detailLoading.value=false}}
function beforeUnload(event:BeforeUnloadEvent){if(pending.value){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(async()=>saving.value?false:!pending.value||await confirmDiscard())
watch(tab,next=>{search.value='';if(next==='api_access')void loadKeys();if(next==='logs'&&!logsReady.value)void loadLogs()})
onMounted(()=>{void load();if(tab.value==='api_access')void loadKeys();if(tab.value==='logs')void loadLogs();window.addEventListener('beforeunload',beforeUnload);clockTimer=setInterval(()=>{clockNow.value=Date.now()},30000)})
onBeforeUnmount(()=>{if(clockTimer)clearInterval(clockTimer);disposed=true;logGeneration++;detailGeneration++;for(const request of requests)request.abort();window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template>
<div class="gateway-security-page module-page">
<PageHeader title="网关安全"><el-button :loading="loading" :disabled="saving" @click="reload">重新加载</el-button></PageHeader>
<div class="panel module-panel" v-loading="loading">
<ManagementTabs :value="tab" :items="securityTabs" @change="changeTab"/>
<el-alert v-if="loadError" :title="loadError" type="error" :closable="false" show-icon class="gap"/>
<template v-if="config">
<div v-if="otherDrafts.length" class="draft-notice"><UiIcon name="info"/><span>{{otherDrafts.join('、')}}有未保存的修改，切换标签会保留草稿。</span></div>
<section v-if="isAccess" class="security-section">
<div class="section-heading"><div><h3>{{securityTabs[tab]}}</h3><p>{{scopeNotes[tab]}}</p></div><el-tag :type="config[tab].enabled?'warning':'info'">{{config[tab].enabled?'访问限制已开启':'访问限制已关闭'}}</el-tag></div>
<el-form label-width="110px" class="security-form"><el-form-item label="访问限制"><el-switch v-model="config[tab].enabled" active-text="开启" inactive-text="关闭"/><span class="field-hint">关闭时允许所有来源访问{{tab==='admin_access'?'登录页':''}}。</span></el-form-item><el-form-item label="控制方式"><el-radio-group v-model="config[tab].mode"><el-radio-button value="blacklist">黑名单</el-radio-button><el-radio-button value="whitelist">白名单</el-radio-button></el-radio-group><span class="field-hint">切换模式会使用当前地址列表。</span></el-form-item></el-form>
<div class="module-note">{{config[tab].mode==='whitelist'?'仅允许列表内的 IP / 网段访问，其他来源拒绝。':'拒绝列表内的 IP / 网段，其他来源允许访问。'}}<template v-if="tab!=='api_access'">当前管理员 IP：<strong>{{currentIP}}</strong>。启用白名单前会检查该地址，避免无法登录。</template><template v-else>未绑定 IP 的 API Key 仍受全局及 API 来源规则约束。</template></div>
<div class="toolbar module-filters"><el-input v-model="search" clearable placeholder="搜索 IP 或网段" class="search"/><span class="muted">共 {{networkCount}} 条地址</span></div>
<div class="toolbar module-actions"><el-button type="primary" @click="editNetwork()">添加 IP / 网段</el-button><el-button v-if="tab!=='api_access'" :loading="validating" @click="addCurrentIP">加入当前管理员 IP</el-button><span class="muted">支持单个添加及按行批量添加。</span></div>
<el-table :data="networkPageRows" row-key="address"><template #empty><EmptyState title="暂无地址规则" description="添加 IP 或 CIDR 网段后，保存当前标签生效。"/></template><el-table-column prop="address" label="IP / 网段" min-width="260"/><el-table-column prop="family" label="地址版本" width="120"/><el-table-column prop="type" label="类型" width="140"/><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="editNetwork(row.index)">编辑</el-button><el-button link type="danger" @click="removeNetwork(row.index)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="networkPage" v-model:page-size="networkSize" :page-sizes="[20,50,100]" :total="networkRows.length" layout="total, sizes, prev, pager, next" @size-change="networkPage=1"/>
<template v-if="tab==='api_access'"><div class="section-heading secondary-heading"><div><h3>API Key IP 绑定</h3><p>仅允许绑定列表中的来源使用该 Key。未绑定的 Key 不受此项限制。</p></div><el-button type="primary" @click="editBinding()">添加绑定</el-button></div><el-alert v-if="keysError" :title="keysError" type="error" :closable="false" show-icon class="gap"><el-button link @click="loadKeys(true)">重新加载 API Key</el-button></el-alert><div class="toolbar module-filters"><el-input v-model="bindingSearch" clearable placeholder="搜索 API Key 名称或绑定地址" class="search"/><span class="muted">共 {{config.key_bindings.length}} 个绑定</span></div><el-table :data="bindingPageRows" row-key="key_id" v-loading="keysLoading"><template #empty><EmptyState title="暂无 API Key IP 绑定" description="选择 API Key 并配置允许访问的 IP 或网段。"/></template><el-table-column prop="label" label="API Key" min-width="260" show-overflow-tooltip/><el-table-column label="允许来源" min-width="260"><template #default="{row}"><div class="address-tags"><el-tag v-for="address in row.addresses" :key="address" size="small">{{address}}</el-tag></div></template></el-table-column><el-table-column label="操作" width="160"><template #default="{row}"><el-button link type="primary" @click="editBinding(row.index)">编辑</el-button><el-button link type="danger" @click="config.key_bindings.splice(row.index,1)">解除绑定</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="bindingPage" v-model:page-size="bindingSize" :page-sizes="[20,50,100]" :total="bindingRows.length" layout="total, sizes, prev, pager, next" @size-change="bindingPage=1"/></template>
</section>
<section v-else-if="tab==='rate'" class="security-section"><div class="section-heading"><div><h3>请求频率限制</h3><p>分别限制来源 IP 和 API Key 的每分钟请求数量。</p></div></div><el-form label-position="top" class="settings-grid"><div class="setting-block"><el-form-item label="单 IP 请求上限"><el-input-number v-model="config.ip_rpm" :min="0" :max="1000000" controls-position="right"/><span class="unit">次 / 分钟</span></el-form-item><p class="muted">覆盖后台接口与 AI API，同一来源 IP 的请求共享额度。</p><el-tag :type="config.ip_rpm?'warning':'info'">{{config.ip_rpm?'已开启 IP 限流':'IP 限流已关闭'}}</el-tag></div><div class="setting-block"><el-form-item label="单 API Key 请求上限"><el-input-number v-model="config.key_rpm" :min="0" :max="1000000" controls-position="right"/><span class="unit">次 / 分钟</span></el-form-item><p class="muted">在 API Key 验证后计数，同一 Key 在不同 IP 上共享额度。</p><el-tag :type="config.key_rpm?'warning':'info'">{{config.key_rpm?'已开启 Key 限流':'Key 限流已关闭'}}</el-tag></div></el-form><div class="module-note">填写 0 表示关闭该项限流。超限返回 HTTP 429，并通过 Retry-After 响应头提示重试等待时间；窗口到期后自动恢复。</div></section>
<section v-else-if="tab==='login'" class="security-section"><div class="section-heading"><div><h3>登录安全</h3><p>限制账号连续失败次数，达到上限后自动锁定。</p></div></div><el-form label-position="top" class="settings-grid"><div class="setting-block"><el-form-item label="连续登录失败上限"><el-input-number v-model="config.login_max_attempts" :min="1" :max="50" controls-position="right"/><span class="unit">次</span></el-form-item><p class="muted">允许设置 1 至 50 次。成功登录清除账号失败计数。</p></div><div class="setting-block"><el-form-item label="自动锁定时间"><el-input-number v-model="config.login_lock_seconds" :min="30" :max="86400" controls-position="right"/><span class="unit">秒</span></el-form-item><p class="muted">允许设置 30 秒至 24 小时；当前约 {{Math.round(config.login_lock_seconds/60*10)/10}} 分钟。</p></div></el-form><div class="module-note">达到失败上限后拒绝继续登录，锁定到期后可以重试。登录失败与账号锁定会记录到安全日志；参数与系统设置中的登录保护同步。</div><el-button @click="changeTab('logs')">查看登录安全日志</el-button></section>
<section v-else-if="tab==='bans'" class="security-section"><div class="section-heading"><div><h3>IP封禁</h3><p>管理临时与永久封禁，到期的临时规则自动失效。</p></div><el-tag type="info">共 {{config.bans.length}} 条记录</el-tag></div><div class="toolbar module-filters"><el-input v-model="search" clearable placeholder="搜索 IP、网段或封禁原因" class="search"/><el-select v-model="banStatus" clearable placeholder="全部状态" class="filter"><el-option value="temporary" label="临时封禁"/><el-option value="permanent" label="永久封禁"/><el-option value="expired" label="已到期"/></el-select><el-button @click="search='';banStatus=''">重置</el-button></div><div class="toolbar module-actions"><el-button type="primary" @click="editBan()">添加封禁</el-button><span class="muted">封禁优先于白名单；添加、修改或解除后保存生效。</span></div><el-table :data="banPageRows"><template #empty><EmptyState title="暂无封禁记录" description="可以添加临时或永久 IP / 网段封禁。"/></template><el-table-column prop="address" label="IP / 网段" min-width="200"/><el-table-column label="状态" width="130"><template #default="{row}"><el-tag :type="row.state==='expired'?'info':'danger'" size="small">{{row.state==='expired'?'已到期':row.state==='permanent'?'永久封禁':'临时封禁'}}</el-tag></template></el-table-column><el-table-column label="到期时间" min-width="190"><template #default="{row}">{{row.expires_at?formatDate(row.expires_at):'永久有效'}}</template></el-table-column><el-table-column prop="reason" label="封禁原因" min-width="200" show-overflow-tooltip/><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="editBan(row.index)">编辑</el-button><el-button link type="danger" @click="removeBan(row.index)">解除封禁</el-button></template></el-table-column></el-table></section>
<section v-else-if="tab==='proxies'" class="security-section"><div class="section-heading"><div><h3>可信代理</h3><p>仅指定代理可传递 X-Forwarded-For 和 X-Real-IP 来源信息。</p></div><el-tag type="info">{{networkCount?'已配置 '+networkCount+' 条':'不信任转发头'}}</el-tag></div><div class="module-note">未配置的来源按真实连接地址识别。代理链从右向左检查，停止在第一个不可信节点；不允许使用 0.0.0.0/0 或 ::/0 信任所有来源。修改时会重新检查当前管理员访问权限。</div><div class="toolbar module-filters"><el-input v-model="search" clearable placeholder="搜索代理 IP 或网段" class="search"/><span class="muted">共 {{networkCount}} 条代理地址</span></div><div class="toolbar module-actions"><el-button type="primary" @click="editNetwork()">添加可信代理</el-button><span class="muted">仅添加实际使用的代理服务器或代理网段。</span></div><el-table :data="networkPageRows" row-key="address"><template #empty><EmptyState title="暂无可信代理" description="默认忽略客户端自行发送的转发头。"/></template><el-table-column prop="address" label="代理 IP / 网段" min-width="260"/><el-table-column prop="family" label="地址版本" width="120"/><el-table-column prop="type" label="类型" width="140"/><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="editNetwork(row.index)">编辑</el-button><el-button link type="danger" @click="removeNetwork(row.index)">删除</el-button></template></el-table-column></el-table></section>
<section v-else-if="tab==='logs'" class="security-section"><div class="toolbar module-filters"><el-input v-model="logIP" clearable placeholder="来源 IP（精确匹配）" class="search" @keyup.enter="queryLogs"/><el-select v-model="logEvent" clearable placeholder="全部事件" class="filter"><el-option v-for="(label,value) in events" :key="value" :value="value" :label="label"/></el-select><el-date-picker v-model="logRange" type="datetimerange" start-placeholder="开始时间" end-placeholder="结束时间" class="date-filter"/><el-button type="primary" :loading="logLoading" @click="queryLogs">查询</el-button><el-button @click="resetLogs">重置</el-button><el-button :loading="logLoading" @click="loadLogs">刷新</el-button></div><p class="muted log-note">默认查询最近 7 天，单次时间范围最多 31 天；显示时间使用系统设置的时区。不记录密码、API Key 原文或对话内容。</p><el-alert v-if="logError" :title="logError" type="error" :closable="false" show-icon class="gap"/><el-table :data="logItems" v-loading="logLoading"><template #empty><EmptyState :title="logError?'安全日志加载失败':'暂无安全日志'" description="调整筛选条件或时间范围后重新查询。"/></template><el-table-column label="时间" min-width="180"><template #default="{row}">{{formatDate(row.created_at)}}</template></el-table-column><el-table-column label="事件" min-width="180"><template #default="{row}"><el-tag :type="row.event.startsWith('gateway_security_')?'info':'warning'" size="small">{{events[row.event]||row.event}}</el-tag></template></el-table-column><el-table-column prop="ip" label="来源 IP" min-width="150"/><el-table-column label="API Key ID" width="120"><template #default="{row}">{{row.key_id||'—'}}</template></el-table-column><el-table-column prop="request_id" label="请求 ID" min-width="260" show-overflow-tooltip/><el-table-column label="操作" width="80"><template #default="{row}"><el-button link type="primary" @click="showLog(row)">详情</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :page-sizes="[20,50,100]" :total="total" layout="total, sizes, prev, pager, next" @size-change="page=1;loadLogs()" @current-change="loadLogs"/></section>
<div v-if="tab!=='logs'" class="security-save"><div><strong>{{securityTabs[tab]}}</strong><el-tag :type="currentDirty?'warning':'info'" size="small">{{currentDirty?'有未保存的修改':'配置已同步'}}</el-tag><p>仅保存当前标签的配置，保存后立即生效。</p></div><div class="save-actions"><el-button :disabled="!currentDirty||saving" @click="resetCurrent">撤销更改</el-button><el-button type="primary" :disabled="!currentDirty" :loading="saving" @click="save">保存{{securityTabs[tab]}}</el-button></div></div>
</template>
</div>
<el-dialog v-model="networkDialog" :title="networkIndex===null?(networkTab==='proxies'?'添加可信代理':'添加 IP / 网段'):'编辑地址'" width="600px" :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="IP / CIDR 网段" required><el-input v-model="networkInput" type="textarea" :rows="7" maxlength="24000" placeholder="每行一条，例如：192.168.31.10、192.168.31.0/24、2001:db8::/32"/></el-form-item><p class="muted">{{networkIndex===null?'支持按行批量添加，重复地址会自动合并。':'编辑时只填写一个 IP 或网段。'}}单个 IP 将规范化为 IPv4 /32 或 IPv6 /128。</p></el-form><template #footer><el-button :disabled="validating" @click="networkDialog=false">取消</el-button><el-button type="primary" :loading="validating" @click="saveNetwork">{{networkIndex===null?'添加':'确定'}}</el-button></template></el-dialog>
<el-dialog v-model="bindingDialog" :title="bindingIndex===null?'添加 API Key IP 绑定':'编辑 API Key IP 绑定'" width="640px" :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="API Key" required><el-select v-model="bindingForm.key_id" filterable :loading="keysLoading" :disabled="bindingIndex!==null" placeholder="选择 API Key" style="width:100%"><el-option v-for="key in keys" :key="key.id" :value="key.id" :label="key.label"/></el-select></el-form-item><el-form-item label="允许访问的 IP / 网段" required><el-input v-model="bindingForm.addresses" type="textarea" :rows="6" maxlength="5000" placeholder="每行一个 IP / CIDR，至少填写一条"/></el-form-item><p class="muted">每个 API Key 最多绑定 100 条地址；名单外的来源会收到 HTTP 403。</p><el-alert v-if="keysError" :title="keysError" type="error" :closable="false"/></el-form><template #footer><el-button :disabled="validating" @click="bindingDialog=false">取消</el-button><el-button type="primary" :loading="validating" @click="saveBinding">确定</el-button></template></el-dialog>
<el-dialog v-model="banDialog" :title="banIndex===null?'添加 IP 封禁':'编辑 IP 封禁'" width="600px" :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="IP / CIDR 网段" required><el-input v-model="banForm.address" placeholder="填写一个 IP 或网段" maxlength="100"/></el-form-item><el-form-item label="封禁方式"><el-radio-group v-model="banForm.permanent"><el-radio-button :value="false">临时封禁</el-radio-button><el-radio-button :value="true">永久封禁</el-radio-button></el-radio-group></el-form-item><el-form-item v-if="!banForm.permanent" label="封禁时长" required><el-input-number v-model="banForm.minutes" :min="1" :max="525600" controls-position="right"/><span class="unit">分钟</span><p class="field-hint">确认后计算到期时间，到期自动失效。</p></el-form-item><el-form-item label="封禁原因"><el-input v-model="banForm.reason" type="textarea" :rows="3" maxlength="200" show-word-limit placeholder="可选，记录封禁原因"/></el-form-item><el-alert title="保存前会检查当前管理员 IP，拒绝导致无法访问的封禁配置。" type="info" :closable="false"/></el-form><template #footer><el-button :disabled="validating" @click="banDialog=false">取消</el-button><el-button type="primary" :loading="validating" @click="saveBan">确定</el-button></template></el-dialog>
<el-drawer v-model="detailOpen" title="安全日志详情" size="620px" @close="detailGeneration++;logDetail=null"><div v-loading="detailLoading"><el-descriptions v-if="logDetail" :column="1" border><el-descriptions-item label="事件">{{events[logDetail.event]||logDetail.event}}</el-descriptions-item><el-descriptions-item label="时间">{{formatDate(logDetail.created_at)}}</el-descriptions-item><el-descriptions-item label="来源 IP">{{logDetail.ip||'—'}}</el-descriptions-item><el-descriptions-item label="API Key ID">{{logDetail.key_id||'—'}}</el-descriptions-item><el-descriptions-item label="管理员 ID">{{logDetail.actor_id||'—'}}</el-descriptions-item><el-descriptions-item label="请求 ID">{{logDetail.request_id||'—'}}</el-descriptions-item><el-descriptions-item label="结果">{{logDetail.result==='success'?'成功':'拦截 / 失败'}}</el-descriptions-item><el-descriptions-item label="日志 ID">{{logDetail.id}}</el-descriptions-item></el-descriptions></div></el-drawer>
</div>
</template>
<style scoped>
.gateway-security-page.module-page :deep(.management-tabs .el-tabs__item){padding:0 16px}.security-section{min-height:300px}.section-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:22px}.section-heading h3{font-size:16px;margin:0 0 8px}.section-heading p{font-size:13px;color:var(--muted);line-height:1.7;margin:0}.security-form{max-width:1000px}.field-hint{font-size:13px;color:var(--muted);line-height:1.7;margin-left:16px}.search{width:280px}.filter{width:180px}.toolbar{flex-wrap:wrap}.date-filter{flex:1;min-width:300px!important}.secondary-heading{padding-top:28px;margin-top:28px;border-top:1px solid var(--line)}.address-tags{display:flex;flex-wrap:wrap;gap:6px;max-height:120px;overflow:auto}.settings-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;margin-bottom:24px}.setting-block{padding:24px;background:var(--soft);border:1px solid var(--line);border-radius:10px}.setting-block .muted{font-size:13px;line-height:1.7}.unit{margin-left:12px;color:var(--muted);font-size:13px}.gap{margin-bottom:18px}.log-note{font-size:13px;line-height:1.7;margin:0 0 18px}.draft-notice{display:flex;gap:8px;padding:12px 16px;margin-bottom:18px;border:1px solid var(--el-color-warning-light-7);border-radius:8px;background:var(--el-color-warning-light-9);color:var(--el-color-warning);font-size:13px}.draft-notice svg{width:16px;height:16px;flex-shrink:0}.security-save{position:sticky;bottom:16px;display:flex;justify-content:space-between;align-items:center;gap:20px;padding:16px 20px;margin-top:24px;background:var(--surface);border:1px solid var(--line);border-radius:10px;box-shadow:0 4px 16px #00000008;z-index:4}.security-save strong{font-size:14px;margin-right:12px}.security-save p{margin:6px 0 0;font-size:12px;color:var(--muted)}.save-actions{display:flex;gap:10px}.save-actions .el-button+.el-button{margin-left:0}.security-section :deep(.el-table__empty-block){min-height:200px}.gateway-security-page :deep(.el-dialog){max-width:calc(100vw - 32px)}.gateway-security-page :deep(.el-drawer){max-width:100vw}.security-section :deep(.el-form-item){margin-bottom:22px}@media(max-width:1000px){.settings-grid{grid-template-columns:1fr}.date-filter{min-width:260px!important}}@media(max-width:760px){.security-save{align-items:flex-start;flex-direction:column;padding:14px}.save-actions{align-self:flex-end}.section-heading{flex-wrap:wrap}.security-form :deep(.el-form-item__label){width:95px!important}.field-hint{margin:8px 0 0;width:100%}.search,.filter{width:100%}.date-filter{width:100%!important;min-width:0!important;flex:auto}.setting-block{padding:18px}}
</style>
